def can_reserve(used: int, requested: int, capacity: int) -> bool:
    if used < 0 or used > 65535 or requested < 0 or requested > 65535 or capacity < 0 or capacity > 65535:
        return False
    if used > capacity:
        return False
    remaining = capacity - used
    if requested <= remaining:
        return True
    return False

